import {resolveQueueParish} from './parish-queue-scope.js';
import {reportDateOnly} from './parish-report-print.js';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function buildRecordReport({parish,records,config,labels,date=new Date().toISOString()}){
 const value=(row,key)=>key==='created_at'||key==='marriage_date'?reportDateOnly(row[key]):row[key]===null||row[key]===undefined||row[key]===''?'Not recorded':String(row[key]);
 const used=new Set(['id',config.name]);
 const columns=[{label:'Record No.',get:row=>value(row,'id')},{label:'Name',get:row=>value(row,config.name)}];
 for(const [keys,label]of [[['year_baptism','month_batism','date_batism'],'Baptism date'],[['year_confirm','month_confirm','date_baptism'],'Confirmation date'],[['year_birth','month_birth','day_birth'],'Birth date']]){
  if(!config.fields.includes(keys[0]))continue;keys.forEach(key=>used.add(key));columns.push({label,get:row=>keys.map(key=>row[key]).filter(item=>item!==null&&item!==undefined&&item!=='').reverse().join(' ')||'Not recorded'});
 }
 for(const key of ['marriage_date','party_role','location','minister'])if(config.fields.includes(key)){used.add(key);columns.push({label:labels[key]||key,get:row=>value(row,key)});}
 const extra=config.fields.filter(key=>!used.has(key));
 const table=(cols)=>'<table><thead><tr><th scope="col">No.</th>'+cols.map(column=>'<th scope="col">'+esc(column.label)+'</th>').join('')+'</tr></thead><tbody>'+records.map((row,index)=>'<tr><td>'+(index+1)+'</td>'+cols.map(column=>'<td>'+esc(column.get(row))+'</td>').join('')+'</tr>').join('')+'</tbody></table>';
 const body=records.length?table(columns)+(extra.length?'<h2>Additional register details</h2>'+table([columns[0],columns[1],...extra.map(key=>({label:labels[key]||key,get:row=>value(row,key)}))]):''):'<p>No records match these filters.</p>';
 return '<!doctype html><html lang="en"><head><meta charset="utf-8"><title>'+esc(config.title)+'</title><style>@page{size:A4 landscape;margin:12mm}body{font:12px/1.6 Arial,sans-serif;color:#24364d;margin:24px;background:#fff}header{text-align:center;border-bottom:2px solid #324d70;padding-bottom:16px;margin-bottom:24px}h1{font-size:21px;margin:5px 0}h2{font-size:16px;margin:20px 0 10px}header p{font-size:11px;color:#718197;margin:4px 0}table{width:100%;border-collapse:collapse;font-size:10px}th,td{padding:7px 8px;border:1px solid #dce3ec;text-align:left;vertical-align:top;overflow-wrap:anywhere}thead{display:table-header-group}th{background:#eff3f8;font-size:11px;color:#506782}article{break-inside:auto;margin-bottom:28px}tr{break-inside:avoid}h2{break-after:avoid}footer{border-top:1px solid #dce3ec;padding-top:10px;color:#8290a1;font-size:10px}.actions{display:flex;justify-content:center;gap:10px;margin:18px 0}.actions button{padding:9px 16px;border:1px solid #ccd7e8;background:#f4f7fc;border-radius:6px;color:#36577d;cursor:pointer}@media print{body{margin:0}.actions{display:none}}</style></head><body><div class="actions"><button onclick="window.print()">Print / Save as PDF</button><button onclick="const blob=new Blob([document.documentElement.outerHTML],{type:\'text/html;charset=utf-8\'});const url=URL.createObjectURL(blob);const a=document.createElement(\'a\');a.href=url;a.download=\'parish-record-report.html\';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)">Download report</button><button onclick="window.close()">Close</button></div><header><p>PARISH RECORDS</p><h1>'+esc(parish)+'</h1><h2>'+esc(config.title)+'</h2><p>Report date: '+esc(reportDateOnly(date))+' | '+records.length+' record(s)</p></header>'+body+'<footer>Prepared from the parish record register. Dates are shown without time.</footer></body></html>';
}
export async function previewRecordReport({records,config,labels,session,request,previewWindow}){
 const popup=previewWindow||window.open('','_blank','width=960,height=760');if(!popup){window.alert('Please allow the record preview window, then try again.');return;}
 popup.document.write('<!doctype html><title>Record report preview</title><p style="font:14px Arial;padding:24px">Preparing record report...</p>');popup.document.close();
 try{const parish=await resolveQueueParish(session,(table,query)=>request('/rest/v1/'+table+'?'+query,{accessToken:session.accessToken}));popup.document.open();popup.document.write(buildRecordReport({parish:parish.parish_name,records,config,labels}));popup.document.close();popup.focus();}catch(error){popup.document.body.textContent='Could not prepare record report: '+error.message;}
}
